<template>
  <div slot="header">
    <div id="salary-education" :style="{width: '100%', height: '300px'}"></div>
    <div class="font-weight-thin text-xs-center grey--text" >
      <span class="font-weight-bold">说明</span>：学历越高，平均薪水越高<br>
    </div>
  </div>
</template>

<script>
const axios = require('axios');
export default {
  data: () => ({
  }),
  mounted() {
    this.drawGraph();
  },
  methods: {
    drawGraph(){
        // 基于准备好的dom，初始化echarts实例
        let myChart = this.$echarts.init(document.getElementById('salary-education'));

        axios.get('./data/salary-education.json?v=1').then((response) => {
          let rs_data = response.data;
          let option = {
              title: {
                  text: '学历与平均薪水',
                  left: 'center'
                },
              color: ['#3398DB'],
              tooltip : {
                  trigger: 'axis',
                  axisPointer : {            // 坐标轴指示器，坐标轴触发有效
                      type : 'shadow'        // 默认为直线，可选为：'line' | 'shadow'
                  }
              },
              grid: {
                  left: '3%',
                  right: '4%',
                  bottom: '3%',
                  containLabel: true
              },
              xAxis : [
                  {
                      type : 'category',
                      data : rs_data.x,
                      axisTick: {
                          alignWithLabel: true
                      }
                  }
              ],
              yAxis : [
                  {
                      type : 'value'
                  }
              ],
              series : [
                  {
                      name:'直接访问',
                      type:'bar',
                      barWidth: '60%',
                      data: rs_data.y
                  }
              ]
          };
          // 绘制图表
          myChart.setOption(option);
        });
    },
  }
}
</script>
